#!/usr/bin/env python3
"""Write Python's `SUPPORTED_KINDS` order for the native ready list.

`daemon.ready` advertises the natively served kinds in the order Python lists
them. Regenerate after Python adds or moves a kind; pass --check to fail on
drift instead of writing.
"""
import argparse
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT))
from kassiber.daemon import SUPPORTED_KINDS  # noqa: E402

DEST = ROOT / "crates/daemon/src/kind_order.rs"


def render():
    lines = [
        "//! Python's `SUPPORTED_KINDS` order; generated by",
        "//! `crates/daemon/scripts/gen_kind_order.py`. Do not edit.",
        "",
        "pub(crate) const PYTHON: &[&str] = &[",
        *(f'    "{kind}",' for kind in SUPPORTED_KINDS),
        "];",
        "",
    ]
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    text = render()
    if parser.parse_args().check:
        if DEST.read_text() != text:
            raise SystemExit(f"{DEST} is stale; rerun {Path(__file__).name}")
        return
    DEST.write_text(text)


if __name__ == "__main__":
    main()
